/* The live prompt preview rendered above the tabs (see index.js): same card recipe the
   studio's own .preview pane uses (src/components/Studio/styles.module.css), so a segment doc's
   preview reads as part of the same design system rather than a one-off box. */
/* No card around the preview: the SVG already draws its own terminal window, complete with
   border, rounded corners and a drop shadow, so wrapping it in a second bordered surface put a
   frame around a frame. The bare SVG reads cleaner on the page. */
.preview {
  box-sizing: border-box;
  margin-bottom: var(--omp-space-2);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--omp-space-1);
}

/* Same micro-label recipe as the studio's PREVIEW/CONFIG pane labels (.paneLabel in
   Studio/styles.module.css) and the segment catalog's search label - shared tokens, not
   restated sizes/colours. */
.label {
  font-family: var(--ifm-font-family-monospace);
  font-size: var(--omp-label-size);
  letter-spacing: var(--omp-label-tracking);
  text-transform: uppercase;
  color: var(--omp-text-secondary);
}

.svgWrapper {
  display: block;
  width: fit-content;
  max-width: 100%;
}

.svgWrapper :global(svg) {
  display: block;
  max-width: 100%;
  height: auto;
}

/* Wraps the preview and the editor (see EditableConfig in Config.js) for a segment doc whose
   sample config the reader can edit in place. No gap of its own - .preview's own margin-bottom
   already spaces it from whatever follows, same as it did when that "whatever" was the plain
   <Tabs/> this replaces for a matched segment doc. */
.editableConfig {
  display: flex;
  flex-direction: column;
}

.wasmMessage {
  margin: 0;
  font-size: var(--omp-text-body);
  color: var(--omp-text-secondary);
}

.error {
  margin: 0;
  font-size: var(--omp-text-body);
  font-family: var(--ifm-font-family-monospace);
  white-space: pre-wrap;
  color: var(--ifm-color-danger);
}

/* Copy / Open in Studio - same micro-label recipe as the format tabs beside them read from
   (Infima's own .tabs__item, see ConfigEditor/index.js), styled as a bordered pill instead of an
   underline so the two kinds of control - "pick a language" vs. "do something with this text" -
   don't visually collapse into one row of identical tabs. */
.action {
  padding: 0.1rem 0.4rem;
  font-family: var(--ifm-font-family-monospace);
  font-size: var(--omp-label-size);
  letter-spacing: var(--omp-label-tracking);
  text-transform: uppercase;
  color: var(--omp-text-secondary);
  background: none;
  border: 1px solid var(--omp-card-border-color);
  border-radius: var(--omp-radius-sm);
  cursor: pointer;
  text-decoration: none;
}

.action:hover {
  color: var(--ifm-color-primary);
  border-color: var(--ifm-color-primary);
  text-decoration: none;
}

.actionDisabled {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

/* Preview above the editor, both full width, rather than two columns. A rendered
   prompt is a wide, short artifact - 120 columns is roughly 1165px - so a half-width
   pane scales it down by more than half and the text stops being readable, which
   defeats the point of a live preview. Stacked, it renders close to 1:1 on a normal
   desktop and only scales down on genuinely narrow screens. */
.studio {
  display: flex;
  flex-direction: column;
  gap: var(--omp-space-3);
  margin-top: 1.5rem;
}

/* Wraps the preview only - the editor's own pane/paneLabel live in ConfigEditor/styles.module.css
   now (see index.js), which uses the same recipe so the two panes still read as one family. */
.pane {
  display: flex;
  flex-direction: column;
  gap: var(--omp-space-1);
  min-width: 0;
}

/* Verbatim copy of SegmentCatalog/styles.module.css's .lbl - same label tokens. */
.paneLabel {
  font-family: var(--ifm-font-family-monospace);
  font-size: var(--omp-label-size);
  letter-spacing: var(--omp-label-tracking);
  text-transform: uppercase;
  color: var(--omp-text-secondary);
}

/* No min-height: the preview is exactly as tall as the prompt it drew. Giving it
   the editor's height left most of the pane empty, since a prompt is a few rows and
   an editor is dozens. */
.preview {
  box-sizing: border-box;
  padding: var(--omp-space-2);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--omp-space-2);
  overflow: auto;
  border: 1px solid var(--omp-card-border-color);
  border-radius: var(--omp-card-radius);
  background: var(--omp-card-background);
}

.svgWrapper {
  display: block;
  width: fit-content;
  max-width: 100%;
}

.svgWrapper :global(svg) {
  display: block;
  max-width: 100%;
  height: auto;
}

.wasmMessage,
.hint {
  margin: 0;
  font-size: var(--omp-text-body);
  color: var(--omp-text-secondary);
}

.error {
  margin: 0;
  font-size: var(--omp-text-body);
  font-family: var(--ifm-font-family-monospace);
  white-space: pre-wrap;
  color: var(--ifm-color-danger);
}

/* Shown once, if a segment handed off from a doc page (see studioHandoff.js) couldn't be
   appended - e.g. the session's own config had been left mid-edit and didn't parse. Same
   danger-toned text as .error; not merged with it because the two report on different things
   (a live render failure vs. a one-shot hand-off failure) and can in principle both be true at
   once. */
.notice {
  margin: 0;
  font-size: var(--omp-text-body);
  color: var(--ifm-color-danger);
}

import React, { useCallback, useEffect, useRef, useState } from 'react';
import ConfigEditor from '../ConfigEditor';
import WasmMessage from '../ConfigEditor/WasmMessage';
import { useWasmRenderer } from '../ConfigEditor/useWasmRenderer';
import { buildRenderOptions, RENDER_DATA_JSON } from '../ConfigEditor/renderDefaults';
import { parseConfig, stringifyConfig } from '../ConfigEditor/serialize';
import {
  APPEND_KEY,
  SESSION_KEY,
  trySessionStorageGet,
  trySessionStorageRemove,
  trySessionStorageSet,
} from '../ConfigEditor/studioHandoff';
import { CONFIG_FORMAT, CONFIG_FORMATS, STARTERS } from './config';
import styles from './styles.module.css';

// 120 columns matches the gallery (export_themes.mjs / plugins/themes); see renderDefaults.js
// for the font metrics and sample data this shares with every other live/build-time preview.
const RENDER_OPTIONS = buildRenderOptions(120);

// Rendering itself is local and fast (no network round trip), but re-running it on every
// keystroke would still mean parsing and re-executing every segment's templates on every single
// character typed. 200ms is long enough to coalesce a burst of keystrokes, short enough that the
// preview still feels live.
const DEBOUNCE_MS = 200;

function Studio() {
  const [format, setFormat] = useState(CONFIG_FORMAT);
  const [configText, setConfigText] = useState(STARTERS[CONFIG_FORMAT]);
  // Set once, on mount, if a hand-off from a segment doc's "Open in Studio" couldn't be applied
  // (see the mount effect below) - the append is skipped and this explains why, rather than the
  // segment silently vanishing.
  const [appendNotice, setAppendNotice] = useState(null);

  const { svg, error, wasmStatus, wasmProgress, wasmErrorMessage, render, ensureLoaded } =
    useWasmRenderer({ eager: true });

  const debounceRef = useRef(null);
  // runRender is a useCallback with no deps, so reading `format` from the closure would pin
  // it to whatever was selected on first render. The ref is what the render call reads.
  const formatRef = useRef(CONFIG_FORMAT);

  const runRender = useCallback(
    (text) => {
      render(text, formatRef.current, RENDER_DATA_JSON, RENDER_OPTIONS);
    },
    [render],
  );

  useEffect(() => {
    ensureLoaded();
  }, [ensureLoaded]);

  // Resumes the reader's own session (see studioHandoff.js's SESSION_KEY doc comment) and, if a
  // segment doc queued one, appends its segment on top - so "Open in Studio" really does add to
  // whatever is already here rather than to a pristine starter every time. Runs exactly once, on
  // mount: format/configText are intentionally read as their *initial* values (the plain
  // STARTER), not the current state, since this effect IS what decides what "current" becomes.
  useEffect(() => {
    let baseFormat = CONFIG_FORMAT;
    let baseText = STARTERS[CONFIG_FORMAT];

    const savedRaw = trySessionStorageGet(SESSION_KEY);

    if (savedRaw) {
      try {
        const saved = JSON.parse(savedRaw);

        if (saved && typeof saved.text === 'string' && CONFIG_FORMATS.includes(saved.format)) {
          baseFormat = saved.format;
          baseText = saved.text;
        }
      } catch {
        // Corrupt or foreign sessionStorage value - fall back to the pristine starter.
      }
    }

    const pendingRaw = trySessionStorageGet(APPEND_KEY);

    if (pendingRaw) {
      // One-shot: consumed here regardless of what happens next, so a later, unrelated studio
      // visit never re-applies it.
      trySessionStorageRemove(APPEND_KEY);

      try {
        const payload = JSON.parse(pendingRaw);
        const segment = payload && payload.segment;

        if (segment && typeof segment === 'object' && !Array.isArray(segment)) {
          const parsedBase = parseConfig(baseFormat, baseText);
          const blocks = Array.isArray(parsedBase.blocks) ? parsedBase.blocks : [];
          let promptBlock = blocks.find((b) => b && b.type === 'prompt' && Array.isArray(b.segments));

          if (!promptBlock) {
            promptBlock = blocks.find((b) => b && Array.isArray(b.segments));
          }

          if (!promptBlock) {
            promptBlock = { type: 'prompt', alignment: 'left', segments: [] };
            blocks.unshift(promptBlock);
          }

          promptBlock.segments = [...promptBlock.segments, segment];
          parsedBase.blocks = blocks;

          baseText = stringifyConfig(baseFormat, parsedBase);
        }
      } catch (err) {
        // The spec here is explicit: a config that fails to parse must not be silently
        // discarded. Leave baseText exactly as it was (the restored session, or the pristine
        // starter) and surface why the segment wasn't added.
        setAppendNotice(
          `Could not add the segment from the previous page: ${err.message || err}. ` +
            'Your current config was left unchanged.',
        );
      }
    }

    if (baseFormat !== CONFIG_FORMAT) {
      setFormat(baseFormat);
      formatRef.current = baseFormat;
    }

    if (baseText !== STARTERS[CONFIG_FORMAT]) {
      setConfigText(baseText);
    }
    // Deliberately runs once: this is a mount-time migration from sessionStorage into React
    // state, not a reaction to any prop/state change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Saves the reader's own session on every change (see studioHandoff.js's SESSION_KEY doc
  // comment) so navigating away - to read another segment doc, say - and back finds this studio
  // exactly as it was left, which is what lets a second "Open in Studio" hand-off accumulate on
  // top of the first instead of landing on a fresh pristine starter.
  useEffect(() => {
    trySessionStorageSet(SESSION_KEY, JSON.stringify({ format, text: configText }));
  }, [format, configText]);

  // Render the starter config as soon as the module is ready, so a prompt appears on first
  // paint without the user having to touch the editor.
  useEffect(() => {
    if (wasmStatus === 'ready') {
      runRender(configText);
    }
    // configText is intentionally not a dependency: this effect's only job is the one render
    // that happens the moment the module becomes ready, not every keystroke after - the
    // editor's onChange handles that, debounced.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [wasmStatus, runRender]);

  useEffect(
    () => () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    },
    [],
  );

  // Switching format changes how the text is parsed and highlighted. The text itself is only
  // replaced when it is still the previous format's starter, untouched - swapping it out from
  // under someone who had started editing would throw their work away, and leaving a YAML
  // document to be parsed as TOML would just show a parse error until they retyped it.
  const handleFormatChange = useCallback(
    (next) => {
      setFormat(next);
      formatRef.current = next;

      const pristine = Object.values(STARTERS).includes(configText);
      const text = pristine ? STARTERS[next] : configText;

      if (pristine) {
        setConfigText(text);
      }

      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }

      runRender(text);
    },
    [configText, runRender],
  );

  // react-simple-code-editor's onValueChange hands back the raw string (there is no
  // change event to read a value off of), otherwise this is the exact same debounce as before.
  const handleChange = useCallback(
    (value) => {
      setConfigText(value);

      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }

      debounceRef.current = setTimeout(() => runRender(value), DEBOUNCE_MS);
    },
    [runRender],
  );

  const previewHint = wasmStatus === 'ready' && !svg && !error ? 'Nothing to preview yet.' : null;

  return (
    <div className={styles.studio}>
      {/* Preview first: it is what the page is for, and a prompt is short enough
          that putting it above the editor keeps both in view while typing. */}
      <div className={styles.pane}>
        <span className={styles.paneLabel}>Preview</span>
        <div className={styles.preview}>
          <WasmMessage
            status={wasmStatus}
            progress={wasmProgress}
            errorMessage={wasmErrorMessage}
            className={styles.wasmMessage}
          />

          {error && <p className={styles.error}>{error}</p>}

          {svg && (
            <span className={styles.svgWrapper} dangerouslySetInnerHTML={{ __html: svg }} />
          )}

          {previewHint && <p className={styles.hint}>{previewHint}</p>}
        </div>
      </div>

      {appendNotice && <p className={styles.notice}>{appendNotice}</p>}

      <ConfigEditor
        label="Config"
        srLabel="Theme config"
        format={format}
        formats={CONFIG_FORMATS}
        onFormatChange={handleFormatChange}
        value={configText}
        onChange={handleChange}
      />
    </div>
  );
}

export default Studio;

/* Extracted from Studio/styles.module.css - see that file's own .studio/.preview rules for the
   pane this sits beside. Both consumers (the studio, each segment doc's editor - see index.js)
   wrap this in their own layout; this module only styles the editor itself. */
.pane {
  display: flex;
  flex-direction: column;
  gap: var(--omp-space-1);
  min-width: 0;
}

/* Verbatim copy of SegmentCatalog/styles.module.css's .lbl - same label tokens. */
.paneLabel {
  font-family: var(--ifm-font-family-monospace);
  font-size: var(--omp-label-size);
  letter-spacing: var(--omp-label-tracking);
  text-transform: uppercase;
  color: var(--omp-text-secondary);
}

/* The pane's label and its header controls share a row, so the format tabs (and, on a segment
   doc, the Copy/Open in Studio actions) read as part of naming the pane rather than as controls
   floating above the editor. */
.paneHeader {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--omp-space-2);
}

.headerControls {
  display: flex;
  align-items: baseline;
  gap: var(--omp-space-2);
}

/* The format switch reuses Infima's own .tabs/.tabs__item/.tabs__item--active - the same classes
   @theme/Tabs renders (node_modules/@docusaurus/theme-classic/lib/theme/Tabs/index.js) - so it is
   pixel-identical to the underlined-active-tab look every segment doc already uses for its
   json/yaml/toml code blocks, rather than an approximation. Only the identity of the *element*
   differs (a plain <ul>/<li> here instead of Tabs' own TabsProvider/TabItem machinery, since
   there is no separate panel per tab to show/hide - the one editor's content and language just
   change). formatTabs trims Infima's default spacing, which assumes the tab strip owns the full
   width of a content column; here it is one control among several in a header row. */
.formatTabs {
  margin: 0;
  min-width: 0;
}

.actions {
  display: flex;
  align-items: baseline;
  gap: var(--omp-space-1);
}

/* Visually hidden but still in the accessibility tree - the syntax-highlighted editor's real
   input is react-simple-code-editor's own <textarea>, which can't take a plain aria-label prop,
   so a proper associated <label> stands in for it instead. */
.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* The window chrome around the editor: same border/radius recipe as the preview pane beside it
   (both trace back to the shared --omp-card-* tokens in src/css/custom.css), so the two read as
   one family instead of the preview looking "finished" and the editor looking like a bare
   textarea. overflow: hidden clips the chrome bar and the editor body to the rounded corners. */
.editorWindow {
  border: 1px solid var(--omp-card-border-color);
  border-radius: var(--omp-card-radius);
  overflow: hidden;
}

.editorWindow:focus-within {
  border-color: var(--ifm-color-primary);
}

/* Purely decorative title bar, styled after the traffic-light window controls of a native editor
   window - it has nothing to click and nothing to announce, hence aria-hidden in index.js. */
.editorChrome {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  padding: var(--omp-space-1) var(--omp-space-2);
  background: var(--omp-card-background);
  border-bottom: 1px solid var(--omp-card-border-color);
}

.chromeDot {
  width: 0.6rem;
  height: 0.6rem;
  border-radius: 50%;
  background: var(--ifm-color-emphasis-300);
}

.editorBody {
  display: flex;
  align-items: stretch;
}

/* The line-number gutter. It is a sibling of .editor, not nested inside it, specifically so it
   never shares .editor's own horizontal scrollbar (see .noWrap below) - long lines scroll the
   code without dragging the numbers sideways with them. Its own height and scrollTop are set
   imperatively in index.js (mirroring .editor's rendered box, which can change size on every
   keystroke and via the resize handle) rather than through CSS, since a plain sibling has no
   reliable way to track another flex item's post-resize height. Font, size and line-height are
   identical to .editor's so line N's number lands next to code row N; padding-top/bottom match
   .editor's padding so the first number aligns with the first code line. */
.gutter {
  flex: none;
  box-sizing: border-box;
  width: 2.75rem;
  overflow: hidden;
  padding: var(--omp-space-2) var(--omp-space-2) var(--omp-space-2) 0;
  font-family: var(--ifm-font-family-monospace);
  font-size: var(--omp-text-body);
  line-height: 1.5;
  text-align: right;
  color: var(--omp-text-secondary);
  border-right: 1px solid var(--omp-card-border-color);
  user-select: none;
}

.gutterLine {
  font-variant-numeric: tabular-nums;
}

/* react-simple-code-editor renders its own absolutely-positioned <pre>/<textarea> pair sized to
   fill this element, so it needs an explicit height (min-height) rather than the plain textarea's
   natural content-based sizing - and overflow: auto (set inline, see index.js) so scrolling and
   the resize handle below still work the way they did on a bare textarea. Background and text
   color come from the active Prism theme instead of the card tokens (see index.js's
   DARK_CODE_THEME/LIGHT_CODE_THEME) - matching a real code block's own colors rather than the
   surrounding card chrome, the same way the docs' code fences do. Border and radius live on
   .editorWindow instead, since the gutter sits inside the same frame and a border around .editor
   alone would draw a seam between the two. */
/* No padding here on purpose: it is passed to the Editor's own `padding` prop instead (see
   index.js), because this element's children are absolutely positioned and would ignore it. */
.editor {
  flex: 1;
  min-width: 0;
  min-height: 22rem;
  box-sizing: border-box;
  font-family: var(--ifm-font-family-monospace);
  font-size: var(--omp-text-body);
  line-height: 1.5;
  resize: vertical;
}

.editor:focus-within {
  outline: none;
}

/* Forces one logical line to one visual row (react-simple-code-editor's default whitespace is
   pre-wrap), which is what lets the gutter map a line number to a fixed pixel offset instead of
   having to measure wrapped-row heights. Applied via preClassName/textareaClassName (index.js), so
   it lands on the actual pre/textarea elements rather than the outer .editor container - the
   library sets white-space inline on both, hence !important to win over that. Long lines scroll
   horizontally within .editor instead (its own overflow: auto, set inline in index.js). */
.noWrap {
  white-space: pre !important;
}

/* Left as a literal size rather than --omp-text-body: this is a mobile-only reduction on top of
   the editor's own --omp-text-body, not one of the shared scale's steps. */
@media (max-width: 700px) {
  .editor {
    min-height: 16rem;
    font-size: 0.75rem;
  }

  .gutter {
    width: 2.25rem;
    font-size: 0.75rem;
  }
}

