const textareaId = useId();
const gutterRef = useRef(null);

// One entry per logical line of the config, independent of the (debounced) render - typing a
// newline should renumber the gutter immediately, not on the caller's own debounce timer. Safe
// to derive straight from `value` because .noWrap forces one visual row per logical line, so
// "line N" always means the same thing here as it does in the highlighted code below.
const lineCount = useMemo(() => value.split('\n').length, [value]);
const lineNumbers = useMemo(
  () => Array.from({ length: lineCount }, (_, i) => i + 1),
  [lineCount],
);

// Keeps the gutter's box and scroll position mirroring .editor's own, which react-simple-code-
// editor renders as a plain scrollable div (see styles.module.css's .editor) that the user can
// also resize by dragging its corner. The gutter is a sibling, not a child, of that div (see the
// .gutter comment in styles.module.css), so nothing here happens for free: a ResizeObserver
// catches height changes from the resize handle, and a scroll listener catches the div's own
// scrolling.
useIsomorphicLayoutEffect(() => {
  const textarea = document.getElementById(textareaId);
  const gutter = gutterRef.current;

  if (!textarea || !gutter) {
    return undefined;
  }

  const container = textarea.parentElement;

  if (!container) {
    return undefined;
  }

  const sync = () => {
    gutter.style.height = `${container.clientHeight}px`;
    gutter.scrollTop = container.scrollTop;
  };

  sync();
  container.addEventListener('scroll', sync);

  const resizeObserver = new ResizeObserver(sync);
  resizeObserver.observe(container);

  return () => {
    container.removeEventListener('scroll', sync);
    resizeObserver.disconnect();
  };
}, [textareaId]);

