5	import { buildRenderOptions, RENDER_DATA_JSON } from '../ConfigEditor/renderDefaults';
6	import { parseConfig, stringifyConfig } from '../ConfigEditor/serialize';
7	import {
8	  APPEND_KEY,
9	  SESSION_KEY,
10	  trySessionStorageGet,
11	  trySessionStorageRemove,
12	  trySessionStorageSet,
13	} from '../ConfigEditor/studioHandoff';
14	import { CONFIG_FORMAT, CONFIG_FORMATS, STARTERS } from './config';
15	import styles from './styles.module.css';
16	
17	// 120 columns matches the gallery (export_themes.mjs / plugins/themes); see renderDefaults.js
18	// for the font metrics and sample data this shares with every other live/build-time preview.
19	const RENDER_OPTIONS = buildRenderOptions(120);
20	
21	// Rendering itself is local and fast (no network round trip), but re-running it on every
22	// keystroke would still mean parsing and re-executing every segment's templates on every single
23	// character typed. 200ms is long enough to coalesce a burst of keystrokes, short enough that the
24	// preview still feels live.
25	const DEBOUNCE_MS = 200;
26	
27	function Studio() {
28	  const [format, setFormat] = useState(CONFIG_FORMAT);
29	  const [configText, setConfigText] = useState(STARTERS[CONFIG_FORMAT]);
30	  // Set once, on mount, if a hand-off from a segment doc's "Add to Studio" couldn't be applied
31	  // (see the mount effect below) - the append is skipped and this explains why, rather than the
32	  // segment silently vanishing.
33	  const [appendNotice, setAppendNotice] = useState(null);
34	
35	  const { svg, error, wasmStatus, wasmProgress, wasmErrorMessage, render, ensureLoaded } =
36	    useWasmRenderer({ eager: true });
