}

/* Docs prev/next pagination (Infima's .pagination-nav, rendered by theme-classic's DocPaginator -
   global classes, not CSS modules, so no hashed name to work around here). Infima's defaults
   (1rem padding, a 1rem label, a 0.875rem sublabel) were sized for a generic doc footer and read
   as oversized next to this site's own type scale. Padding steps down to --omp-space-2, the title
   to --omp-text-body, and the "Previous"/"Next" sublabel is rebuilt as the same micro-label recipe
   already used for SegmentCatalog's facet legends and the studio's pane labels (monospace, tracked,
   uppercase, --omp-text-secondary) instead of a plain semibold line - consistent with the rest of
   the site rather than a one-off shrink. Padding uses --omp-space-2 rather than --omp-space-1 so
   the click target stays comfortable on both a long and a short doc page. */
.pagination-nav__link {
  padding: var(--omp-space-2);
  border-color: var(--omp-card-border-color);
  border-radius: var(--omp-card-radius);
}

.pagination-nav__label {
  font-size: var(--omp-text-body);
}

.pagination-nav__sublabel {
  font-family: var(--ifm-font-family-monospace);
  font-size: var(--omp-label-size);
  letter-spacing: var(--omp-label-tracking);
  text-transform: uppercase;
  color: var(--omp-text-secondary);
  font-weight: 400;
  margin-bottom: var(--omp-space-1);
}

