/* The footer takes the navbar's surface, in whichever colour mode is active. Both are chrome
   bracketing the page, so a footer on its own palette (Infima's .footer--dark, which the config
   no longer asks for - see docusaurus.config.js) read as a slab bolted to the bottom, especially
   in light mode where it stayed dark while everything above it was white. Mapping the footer's
   own tokens to the navbar's, rather than restating colours, means a later navbar change carries
   to the footer for free. The box-shadow is the navbar's --ifm-navbar-shadow with its offset
   flipped, so the hairline that separates the navbar from the page below it separates the footer
   from the page above it - which in light mode is the only thing distinguishing either of them
   from a white page. */
.footer {
  --ifm-footer-background-color: var(--ifm-navbar-background-color);
  --ifm-footer-color: var(--ifm-navbar-link-color);
  --ifm-footer-title-color: var(--ifm-navbar-link-color);
  --ifm-footer-link-color: var(--ifm-navbar-link-color);
  box-shadow: 0 -1px 2px 0 #0000001a;
}
CSSEOF
