import Link from "@docusaurus/Link";
import useBaseUrl from "@docusaurus/useBaseUrl";
import useDocusaurusContext from "@docusaurus/useDocusaurusContext";
import { usePluginData } from "@docusaurus/useGlobalData";
import Layout from "@theme/Layout";
import Head from "@docusaurus/Head";
import Tabs from "@theme/Tabs";
import TabItem from "@theme/TabItem";
import CodeBlock from "@theme/CodeBlock";
import classnames from "classnames";
import styles from "./styles.module.css";

// The first two cards are fixed copy; the third's title is built from the segments plugin's
// computed total (see usePluginData below) instead of a hardcoded "117 segments" that would
// silently drift as segments are added or removed.
function buildFeatures(segmentTotal) {
  return [
    {
      title: <>One config, every shell</>,
      description: (
        <>
          Write your prompt once and run it everywhere: PowerShell, Bash, Zsh, Fish, Nu, and
          more. Windows, macOS, Linux, WSL, containers, SSH sessions &mdash; no vendor lock-in.
        </>
      ),
    },
    {
      title: <>Fast by construction</>,
      description: (
        <>
          Built in Go with smart caching and async segment execution. Your prompt renders
          instantly, even with complex configurations and multiple segments running.
        </>
      ),
    },
    {
      title: <>{segmentTotal} segments</>,
      description: (
        <>
          Git status, cloud context, language versions, system metrics and more, composed
          with a template language so your prompt adapts to what you're working on.
        </>
      ),
    },
  ];
}

const shells = [
  "bash",
  "cmd",
  "elvish",
  "fish",
  "nu",
  "powershell",
  "xonsh",
  "yash",
  "zsh",
];

function Feature({ title, description }) {
  return (
    <div className={classnames("col col--4", styles.feature)}>
      <div className={styles.card}>
        <h3>{title}</h3>
        <p>{description}</p>
      </div>
    </div>
  );
}

function Home() {
  const context = useDocusaurusContext();
  const { siteConfig } = context;
  const { total: segmentTotal } = usePluginData("oh-my-posh-segments");
  const features = buildFeatures(segmentTotal);

  const websiteJsonLd = JSON.stringify({
    "@context": "https://schema.org",
    "@type": "WebSite",
    "url": "https://ohmyposh.dev/",
    "name": "Oh My Posh",
    "description": siteConfig.tagline,
  });

  const organizationJsonLd = JSON.stringify({
    "@context": "https://schema.org",
    "@type": "Organization",
    "name": "Oh My Posh",
    "url": "https://ohmyposh.dev/",
    "logo": "https://ohmyposh.dev/img/logo.png",
    "description": siteConfig.tagline,
    "sameAs": [
      "https://github.com/JanDeDobbeleer/oh-my-posh",
    ],
  });

  return (
    <Layout title="Home" description={siteConfig.tagline}>
      <Head>
        <script type="application/ld+json" dangerouslySetInnerHTML={{__html: websiteJsonLd}} />
        <script type="application/ld+json" dangerouslySetInnerHTML={{__html: organizationJsonLd}} />
      </Head>
      <header className={styles.heroBanner}>
        <div className="container">
          <h1 className={classnames("hero__title", styles.heroTitle)}>A prompt that knows where you are.</h1>
          <p className={classnames("hero__subtitle", styles.subtitle)}>{siteConfig.tagline}</p>

          <div className={styles.installBox}>
            <Tabs
              groupId="install-os"
              defaultValue="windows"
              values={[
                { label: "Windows", value: "windows" },
                { label: "macOS", value: "macos" },
                { label: "Linux", value: "linux" },
              ]}
            >
              <TabItem value="windows">
                <CodeBlock language="powershell">
                  winget install JanDeDobbeleer.OhMyPosh --source winget
                </CodeBlock>
              </TabItem>
              <TabItem value="macos">
                <CodeBlock language="bash">
                  brew install jandedobbeleer/oh-my-posh/oh-my-posh
                </CodeBlock>
              </TabItem>
              <TabItem value="linux">
                <CodeBlock language="bash">
                  curl -s https://ohmyposh.dev/install.sh | bash -s
                </CodeBlock>
              </TabItem>
            </Tabs>
            <p className={styles.installNote}>
              Other options and package managers in the{" "}
              <Link to={useBaseUrl("docs/installation/windows")}>installation guide</Link>.
            </p>
          </div>

          <div className={styles.buttons}>
            <Link
              className="button button--primary button--lg"
              to={useBaseUrl("docs/")}
            >
              Get started &rarr;
            </Link>
            <Link
              className="button button--outline button--primary button--lg"
              to={useBaseUrl("docs/themes")}
            >
              Browse themes &rarr;
            </Link>
          </div>

          <div className={styles.heroImageWrapper}>
            <img
              className={styles.heroImage}
              src="/img/hero.png"
              width="1100"
              height="44"
              alt="The default Oh My Posh prompt"
            />
          </div>
        </div>
      </header>
      <main>
        <section className={styles.features}>
          <div className="container">
            <div className="row">
              {features.map((props, idx) => (
                <Feature key={idx} {...props} />
              ))}
            </div>
          </div>
        </section>
        <section className={styles.shellRow}>
          <div className="container">
            <p className={styles.shellList}>Works with {shells.join(" · ")}</p>
          </div>
        </section>
      </main>
    </Layout>
  );
}

export default Home;

