// Switching format changes how the text is parsed and highlighted. The text itself is only
// replaced when it is still the previous format's starter, untouched - swapping it out from
// under someone who had started editing would throw their work away, and leaving a YAML
// document to be parsed as TOML would just show a parse error until they retyped it.
const handleFormatChange = useCallback(
  (next) => {
    setFormat(next);
    formatRef.current = next;

    const pristine = Object.values(STARTERS).includes(configText);
    const text = pristine ? STARTERS[next] : configText;

    if (pristine) {
      setConfigText(text);
    }

    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    runRender(text);
  },
  [configText, runRender],
);

input.new_string:
// Switching format rewrites the config into the format that was picked, keeping whatever the
// reader has typed (see convertConfig). A config that does not parse cannot be rewritten, so
// the switch is refused rather than left half-applied - a JSON document being read as TOML was
// the whole bug.
const handleFormatChange = useCallback(
  (next) => {
    const text = convertConfig(formatRef.current, next, configText);

    if (text === null) {
      setFormatNotice(
        `Could not rewrite this config as ${next}. Fix the errors below and try again.`,
      );
      return;
    }

    setFormatNotice(null);
    setFormat(next);
    formatRef.current = next;
    setConfigText(text);

    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    runRender(text);
  },
  [configText, runRender],
);

