    // that happens the moment the module becomes ready, not every keystroke after - the
    // editor's onChange handles that, debounced.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [wasmStatus, runRender]);

  useEffect(
    () => () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    },
    [],
  );

  // Switching format changes how the text is parsed and highlighted. The text itself is only
  // replaced when it is still the previous format's starter, untouched - swapping it out from
  // under someone who had started editing would throw their work away, and leaving a YAML
  // document to be parsed as TOML would just show a parse error until they retyped it.
  const handleFormatChange = useCallback(
    (next) => {
      setFormat(next);
      formatRef.current = next;

      const pristine = Object.values(STARTERS).includes(configText);
      const text = pristine ? STARTERS[next] : configText;

      if (pristine) {
        setConfigText(text);
      }

      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }

      runRender(text);
    },
    [configText, runRender],
  );

