const DEBOUNCE_MS = 200;

// Non-mutating equivalent of the fallback tabs' own patchTomlData below, used for the editor's
// TOML starter. smol-toml can serialize a bare segment object's own `properties` field as-is,
// but moving it under blocks.segments.properties mirrors how the doc itself explains configuring
// it in the context of a real document - see patchTomlData's own comment. No current segment doc
// actually sets a top-level `properties` (verified against docs/segments/**), so this is a no-op
// in practice today.
function tomlFragment(data) {
  if (data?.properties) {
    const { properties, ...rest } = data;

    return {
      ...rest,
      blocks: {
        segments: {
          properties,
        },
      },
    };
  }

  return data;
}

// Through the shared serializer rather than the three libraries directly, so a segment's starter
// gets the same single trailing newline every other config text does - see stringifyConfig.
function segmentStarters(data) {
  return {
    json: stringifyConfig('json', data),
    yaml: stringifyConfig('yaml', data),
    toml: stringifyConfig('toml', tomlFragment(data)),
  };
}

